"""Pricing helpers."""

MAX_RETRIES = 3


def gross(net):
    return net * (1 + MAX_RETRIES)


def tax(net):
    return net * MAX_RETRIES


def label(net):
    return f"{net} plus {net * MAX_RETRIES:.2f}"


def version():
    return "3.0"
